using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — the SDK resolves HttpClient via DI
/// and creates a new instance of this class per tool invocation.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(HttpClient httpClient, ILogger<JsonPlaceholderTools> logger)
{
    private const string BaseUrl = "https://jsonplaceholder.typicode.com";

    [McpServerTool, Description("Get a single post by its ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID (1–100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var post = await httpClient.GetFromJsonAsync<Post>(
            $"{BaseUrl}/posts/{postId}", cancellationToken);
        return $"[{post!.Id}] {post.Title}\n\n{post.Body}";
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"{BaseUrl}/posts?userId={userId}"
            : $"{BaseUrl}/posts";

        logger.LogInformation("Listing posts (userId={UserId})", userId);
        var posts = await httpClient.GetFromJsonAsync<List<Post>>(url, cancellationToken);
        return string.Join("\n", posts!.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var comments = await httpClient.GetFromJsonAsync<List<Comment>>(
            $"{BaseUrl}/posts/{postId}/comments", cancellationToken);
        return string.Join("\n\n", comments!.Select(c =>
            $"From: {c.Email}\n{c.Body}"));
    }

    [McpServerTool(ReadOnly = true), Description("Search for a user by name or username.")]
    public async Task<string> FindUser(
        [Description("Name or username to search for")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users for '{Query}'", query);
        var users = await httpClient.GetFromJsonAsync<List<User>>(
            $"{BaseUrl}/users", cancellationToken);
        var matches = users!.Where(u =>
            u.Name.Contains(query, StringComparison.OrdinalIgnoreCase) ||
            u.Username.Contains(query, StringComparison.OrdinalIgnoreCase));
        return matches.Any()
            ? string.Join("\n", matches.Select(u => $"{u.Name} (@{u.Username}) — {u.Email}"))
            : "No users found.";
    }
}

// DTOs for the JSONPlaceholder API
public record Post(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("userId")] int UserId,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

public record Comment(
    [property: JsonPropertyName("postId")] int PostId,
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("body")] string Body);

public record User(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("username")] string Username,
    [property: JsonPropertyName("email")] string Email);

